modules[S(55)] = function()
return function(import)
    local Players = game:GetService(S(254))
    local createWindow = import(S(16))(import)
    local i18n = import(S(310))
    local antiAfk = import(S(52))(import)
    local interactionLogger = import(S(30))(import)
    local log = import(S(114))
    local window = createWindow({
        Subtitle = S(50),
    })
    local getCurrentPlot = import(S(34))
    local getPlotParts = import(S(316))
    local dumpInstance = import(S(273))
    local autoMine = import(S(193))(import)
    local autoPlace = import(S(306))(import)
    local autoTakeChest = import(S(284))(import)
    local autoOpenChest = import(S(64))(import)
    local autoSell = import(S(101))(import)
    local autoUpgrade = import(S(25))(import)
    local farmTab = window:AddTab(S(90), S(115))
    farmTab:AddCard(
        S(227),
        S(179)
    ):AddToggle(false, function(state)
        autoMine.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(175),
        S(264)
    ):AddToggle(false, function(state)
        autoPlace.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(216),
        S(223)
    ):AddToggle(false, function(state)
        autoOpenChest.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(56),
        S(68)
    ):AddToggle(false, function(state)
        autoSell.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(100),
        S(282)
    ):AddToggle(false, function(state)
        autoUpgrade.SetEnabled(state)
    end)
    local debugCard = farmTab:AddCard(S(176), S(69))
    local checkBtn
    checkBtn = debugCard:AddButton(S(27), function()
        local plot = getCurrentPlot()
        if not plot then
            checkBtn.Text = S(78)
            log(S(293))
            return
        end
        local parts = getPlotParts(plot)
        local nodeCount = parts.Nodes and #parts.Nodes:GetChildren() or 0
        local holderCount = parts.Holders and #parts.Holders:GetChildren() or 0
        checkBtn.Text = plot.Name
        log(string.format(
            S(235),
            plot.Name, nodeCount, holderCount
        ))
    end)
    local dumpCard = farmTab:AddCard(
        S(155),
        S(130)
    )
    local dumpBtn
    dumpBtn = dumpCard:AddButton(S(317), function()
        local plot = getCurrentPlot()
        if not plot then
            dumpBtn.Text = S(61)
            return
        end
        local ok, err = log(S(250))
        if not ok then
            dumpBtn.Text = S(315)
            dumpCard:SetSubtitle(S(60) .. tostring(err))
            return
        end
        local parts = getPlotParts(plot)
        local firstNode = parts.Nodes and parts.Nodes:GetChildren()[1]
        if firstNode then
            log(S(231) .. firstNode.Name .. S(84))
            dumpInstance(firstNode, log)
        else
            log(S(262))
        end
        local firstHolder = parts.Holders and parts.Holders:GetChildren()[1]
        if firstHolder then
            log(S(280) .. firstHolder.Name .. S(154))
            dumpInstance(firstHolder, log)
        else
            log(S(125))
        end
        dumpBtn.Text = S(161)
    end)
    local toolDumpCard = farmTab:AddCard(
        S(40),
        S(266)
    )
    local toolDumpBtn
    toolDumpBtn = toolDumpCard:AddButton(S(234), function()
        local backpack = Players.LocalPlayer:FindFirstChild(S(26))
        local tool = backpack and backpack:FindFirstChildWhichIsA(S(297))
        if not tool then
            toolDumpBtn.Text = S(35)
            return
        end
        log(S(285) .. tool.Name .. S(221))
        for attrName, attrValue in pairs(tool:GetAttributes()) do
            log(S(292) .. attrName .. S(103) .. tostring(attrValue))
        end
        dumpInstance(tool, log)
        toolDumpBtn.Text = S(313)
    end)
    local settingsTab = window:AddTab(S(169), S(6))
    settingsTab:AddCard(S(137), S(116)):AddToggle(false, function(state)
        antiAfk.SetEnabled(state)
    end)
    settingsTab:AddCard(
        S(11),
        S(83)
    ):AddToggle(false, function(state)
        interactionLogger.SetEnabled(state)
    end)
    settingsTab:AddSlider(S(123), S(14), 50, 150, 100, function(value)
        window:SetScale(value)
    end)
    settingsTab:AddSegmented({ S(131), S(82), S(93) }, 1, function(index, value)
        local code = ({ S(253), S(178), S(76) })[index]
        i18n.SetLanguage(code)
    end)
    window:OnDestroy(function()
        autoMine.SetEnabled(false)
        autoPlace.SetEnabled(false)
        autoTakeChest.SetEnabled(false)
        autoOpenChest.SetEnabled(false)
        antiAfk.SetEnabled(false)
        interactionLogger.SetEnabled(false)
        autoSell.SetEnabled(false)
        autoUpgrade.SetEnabled(false)
    end)
end
end
